import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.Boholvbs.js";const i="/docs/assets/ai-bulk-geolocation.DDcuj6CD.png",n="/docs/assets/ai-bulk-geolocation2.DVhsBiuK.png",r="/docs/assets/ai-bulk-geolocation3.CUxQer5L.png",l="/docs/assets/ai-bulk-geolocation4.BPeJnInI.png",b=JSON.parse('{"title":"AI Bulk Geolocation","description":"","frontmatter":{},"headers":[],"relativePath":"ai-bulk-geolocation/index.md","filePath":"ai-bulk-geolocation.md"}'),c={name:"ai-bulk-geolocation/index.md"};function h(u,e,p,d,g,m){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="ai-bulk-geolocation" tabindex="-1">AI Bulk Geolocation <a class="header-anchor" href="#ai-bulk-geolocation" aria-label="Permalink to &quot;AI Bulk Geolocation&quot;">​</a></h1><p>Bulk Geolocation allows you to georeference many posts at once using AI. This is useful when you have a large archive of posts that were not geolocated when first published.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The Bulk Geolocation system processes posts in batches using WordPress cron (WP-Cron). It selects posts that do not have geolocation data (<code>_related_point</code> meta) and sends them to the AI for analysis.</p><h2 id="setting-up" tabindex="-1">Setting up <a class="header-anchor" href="#setting-up" aria-label="Permalink to &quot;Setting up&quot;">​</a></h2><ol><li>Configure an AI provider in <strong>Jeo → AI</strong> (see <a href="/docs/ai-settings/">AI Settings</a>).</li><li>Go to the <strong>Bulk Geolocation</strong> tab in <strong>Jeo → AI</strong>.</li><li>Select the post types to process, set the confidence threshold, and configure the batch size.</li><li>Start the bulk process.</li></ol><p><img src="'+i+'" alt="AI Bulk Geolocation - Settings"></p><h2 id="processing" tabindex="-1">Processing <a class="header-anchor" href="#processing" aria-label="Permalink to &quot;Processing&quot;">​</a></h2><p>Once started, the system processes posts in the background:</p><ul><li>Each batch selects posts without geolocation data and sends them to the AI.</li><li>A <strong>JEO AI Status</strong> column appears in the WordPress admin post list, showing the georeferencing status for each post.</li><li>Processed posts are marked for review — they are not published automatically.</li></ul><p><img src="'+n+'" alt="AI Bulk Geolocation - Post status"></p><h2 id="reviewing-results" tabindex="-1">Reviewing results <a class="header-anchor" href="#reviewing-results" aria-label="Permalink to &quot;Reviewing results&quot;">​</a></h2><p>After processing, you can review the AI-suggested geolocation for each post:</p><ol><li>Go to the post list and look for posts with a &quot;pending review&quot; AI status.</li><li>Click on a post to open the editor.</li><li>The Geolocation sidebar will show the AI-suggested points.</li><li>Approve or adjust the points as needed.</li></ol><p><img src="'+r+'" alt="AI Bulk Geolocation - Review"></p><p><img src="'+l+'" alt="AI Bulk Geolocation - Review"></p><p>You can also use the <strong>bulk action</strong> on the WordPress post list (<code>edit.php</code>) to approve multiple posts at once. Select the posts, choose <strong>Approve JEO AI Geolocations</strong> from the bulk actions dropdown, and a preview modal will appear showing each post&#39;s suggested locations, confidence scores, and an approve/reject action.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li><strong>Jeo → AI Debug Logs</strong>: View token usage, provider, and model for each AI call.</li><li>The Bulk Geolocation tab shows the current batch progress and any errors encountered.</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>An AI provider must be configured.</li><li>Posts must have title and/or content for the AI to analyze.</li></ul>',21)])])}const f=o(c,[["render",h]]);export{b as __pageData,f as default};
